def footer(canvas, doc):
    canvas.saveState()
    canvas.setStrokeColor(colors.HexColor('#b6c5d0'))
    canvas.line(48,39,564,39)
    canvas.setFont('DejaVu',7)
    canvas.setFillColor(colors.HexColor('#46596a'))
    canvas.drawString(48,26,'Alienorum · Calculation Reference · 2026-11-14')
    canvas.drawRightString(564,26,str(doc.page))
    canvas.restoreState()

class ReferenceDocument(SimpleDocTemplate):
    def afterFlowable(self, flowable):
        if isinstance(flowable, Paragraph) and flowable.style.name == 'Heading':
            title = flowable.getPlainText()
            if title == 'Contents':
                return
            anchor = 'section-' + title.split('.')[0]
            self.canv.bookmarkPage(anchor)
            self.canv.addOutlineEntry(title, anchor, level=0)
            self.notify('TOCEntry', (0, title, self.page, anchor))

doc = ReferenceDocument(str(OUT), pagesize=(612,792), rightMargin=64, leftMargin=64, topMargin=49, bottomMargin=53, title='Alienorum Calculation Reference', author='Alienorum Project', subject='Physical estimates and procedural appearance')
doc.multiBuild(story, onFirstPage=footer, onLaterPages=footer)
